parameters.jsCode:
const body = $json.body || $json;

// Lay thong tin tu request body
const resumeId = body.resumeId;
const candidateName = body.candidateName || "Ứng viên";
const candidateEmail = body.candidateEmail || body.email;
const interviewerEmail = body.interviewerEmail || "";
const companyName = body.companyName || "Tiệm Bánh";
const jobTitle = body.jobTitle || "Nhân viên làm bánh";
const dateRaw = body.interviewDate || ""; // DD/MM/YYYY hoac YYYY-MM-DD
const timeRaw = body.interviewTime || "09:00"; // HH:mm
const durationMinutes = Number(body.durationMinutes) || 45;
const note = body.note || "Phỏng vấn chuyên môn và trao đổi định hướng làm việc.";

// Parse ngay gio
let day, month, year;
if (dateRaw.includes('/')) {
  const parts = dateRaw.split('/');
  day = parts[0].padStart(2, '0');
  month = parts[1].padStart(2, '0');
  year = parts[2];
} else if (dateRaw.includes('-')) {
  const parts = dateRaw.split('-');
  year = parts[0];
  month = parts[1].padStart(2, '0');
  day = parts[2].padStart(2, '0');
} else {
  const now = new Date();
  year = now.getFullYear();
  month = String(now.getMonth() + 1).padStart(2, '0');
  day = String(now.getDate()).padStart(2, '0');
}

const timeParts = timeRaw.split(':');
const hour = timeParts[0].padStart(2, '0');
const minute = timeParts[1].padStart(2, '0');

// Tinh gio UTC theo mui gio Viet Nam (+07:00) tranh loi server UTC
const startUtc = new Date(Date.UTC(Number(year), Number(month) - 1, Number(day), Number(hour) - 7, Number(minute)));
const endUtc = new Date(startUtc.getTime() + durationMinutes * 60 * 1000);

const toVnIso = (d) => {
  const vnTime = new Date(d.getTime() + 7 * 60 * 60 * 1000);
  const y = vnTime.getUTCFullYear();
  const m = String(vnTime.getUTCMonth() + 1).padStart(2, '0');
  const dt = String(vnTime.getUTCDate()).padStart(2, '0');
  const h = String(vnTime.getUTCHours()).padStart(2, '0');
  const min = String(vnTime.getUTCMinutes()).padStart(2, '0');
  return `${y}-${m}-${dt}T${h}:${min}:00+07:00`;
};

const startIso = toVnIso(startUtc);
const endIso = toVnIso(endUtc);

return {
  json: {
    resumeId,
    candidateName,
    candidateEmail,
    interviewerEmail,
    companyName,
    jobTitle,
    interviewDateFormatted: `${day}/${month}/${year}`,
    interviewTimeFormatted: `${hour}:${minute}`,
    startDateTime: startIso,
    endDateTime: endIso,
    durationMinutes,
    note
  }
};

